Translate("esES", "terenthis", {
	title = "Terenthis",
	subtitle = "Vigía del Bosque Negro",
	found = "Auberdine, cerca del puesto de las Centinelas",
	hint = [=[Hable con el elfo de la noche de Auberdine que persigue las señales de la corrupción.]=],
	allegiance = "Auberdine · Elfos de la noche",
	sections = {
		{
			title = "Resumen",
			text = [=[Terenthis es un {link:night-elves}elfo de la noche{/link} de {link:auberdine}Auberdine{/link} que ha jurado encontrar la corrupción en su origen. Algunos de sus parientes fueron rescatados de un {link:furbolgs}fúrbolg{/link} corrompido en {link:teldrassil}Teldrassil{/link}. Desde ese día ha jurado que nadie más de su pueblo sufrirá del mismo modo, y vigila de cerca a los fúrbolgs de {link:darkshore}Costa Oscura{/link}.]=],
		},
		{
			title = "Importancia",
			text = [=[Terenthis fue de los primeros en mostrar lo cerca que había llegado el peligro. Sus exploradores encontraron los campamentos {link:blackwood-furbolgs}Bosque Negro{/link} corrompidos a la vista de {link:auberdine}Auberdine{/link}. Es también amigo de quienes viven solos en lo salvaje, y un amigo en apuros lo encuentra dispuesto.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Envió exploradores a encontrar un campamento {link:furbolgs}fúrbolg{/link} corrompido, y combatientes a diezmar sus filas.
• Confeccionó una capa encantada de pieles de acechaluna que permitía a quien la llevaba pasar inadvertido para las bestias de {link:darkshore}Costa Oscura{/link}.
• Trajo a {link:volcor}Volcor{/link} de vuelta a casa desde el {link:blackwood-den}Cubil del Bosque Negro{/link}.
• Envía sus hallazgos al anciano, {link:thundris-windweaver}Thundris Windweaver{/link}.]=],
		},
	},
	chapters = {
		{
			title = "¿Cuán grande es la amenaza?",
			hint = [=[Encuentre un campamento fúrbolg corrompido cerca de Auberdine.]=],
			text = [=[El campamento al sur de {link:auberdine}Auberdine{/link} era peor de lo que Terenthis había temido. Los {link:blackwood-furbolgs}Bosque Negro{/link} estaban corrompidos, y estaban cerca. Dijo a Auberdine que se preparara para lo que había de venir. También dijo a quienes habían luchado allí que no se lamentaran. Habían reducido la amenaza, aunque el musgo vil siguiera envenenando la tierra.]=],
		},
		{
			title = "Un amo perdido",
			hint = [=[Responda a la llamada de la bestia que llegó sola a Auberdine.]=],
			text = [=[{link:grimclaw}Grimclaw{/link} llegó a {link:auberdine}Auberdine{/link} sin su amo. Terenthis lo comprendió al instante. {link:volcor}Volcor{/link} estaba herido, en algún lugar del sur entre los fúrbolgs. Cosió una capa que ocultaría a su portador de las bestias, y advirtió que su magia fallaría si quien la llevaba hacía algo más que hablar.]=],
		},
	},
	mentions = {
		{ text = "Un amo perdido" },
		{ text = "Huida por la fuerza" },
		{ text = "Huida con sigilo" },
		{ text = "{link:thundris-windweaver}Thundris Windweaver{/link}" },
		{
			text = [=[Viaje a {link:ashenvale}Vallefresno{/link}, una llamada de la centinela Selarin]=],
		},
	},
	bonds = {
		{ id = "volcor", name = "Volcor", note = "su amigo" },
		{ id = "grimclaw", name = "Grimclaw", note = "el compañero de Volcor" },
		{ id = "thundris-windweaver", name = "Thundris Windweaver", note = "el anciano al que informa" },
		{ id = "blackwood-furbolgs", name = "Fúrbolgs Bosque Negro", note = "la corrupción que vigila" },
	},
})

Translate("esES", "onu", {
	title = "Onu",
	subtitle = "Anciano de Sabiduría",
	found = "El Páramo de los Ancestros, en el sur de Costa Oscura",
	hint = [=[Busque al Anciano de Sabiduría en el páramo cercano a las montañas del sur.]=],
	allegiance = "Los Ancianos · Páramo de los Ancestros",
	sections = {
		{
			title = "Resumen",
			text = [=[Onu es un Anciano de Sabiduría, uno de los grandes espíritus del bosque, y guarda el {link:grove-of-the-ancients}Páramo de los Ancestros{/link} en el sur de {link:darkshore}Costa Oscura{/link}. Habla despacio y con largas pausas, y no tiene prisa. Sabe que todas las cosas llegan a su debido tiempo.]=],
		},
		{
			title = "Importancia",
			text = [=[Onu es la memoria de {link:darkshore}Costa Oscura{/link}. Sabe lo que adoran los sectarios del {link:twilight-s-hammer}Martillo Crepuscular{/link}, y sabe dónde cayó uno de sus antiguos señores. Los druidas y eruditos de {link:auberdine}Auberdine{/link} le llevan sus preguntas más graves, y el archidruida {link:fandral-staghelm}Fandral Staghelm{/link} le envía mensajes desde {link:darnassus}Darnassus{/link}.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Envió {link:the-night-watch}vigías{/link} a {link:the-master-s-glaive}El Glaive del Maestro{/link} y supo que el {link:twilight-s-hammer}Martillo Crepuscular{/link} estaba allí.
• Estudió una página arrancada del tomo del culto y sintió en ella la magia de los antiguos.
• Reunió reliquias de {link:ruins-of-mathystra}Mathystra{/link} para saber cómo usa el culto la magia élfica.
• Habla de {link:malfurion-stormrage}Shan'do Stormrage{/link} como de alguien que comprendía la paciencia del bosque.]=],
		},
	},
	chapters = {
		{
			title = "El Glaive del Maestro",
			hint = "Vaya a El Glaive del Maestro a petición del Anciano.",
			text = [=[A Onu le pareció extraño que los {link:naga}naga{/link} hubieran llegado a {link:darkshore}Costa Oscura{/link}. Más extraño aún le pareció que hubiera llegado el {link:twilight-s-hammer}Martillo Crepuscular{/link}. Cuando sus temores se confirmaron, habló del antiguo señor empalado en el Glaive. Ese señor está muerto. Su poder, quizá, no.]=],
		},
		{
			title = "Páginas de los antiguos",
			hint = "Lleve al Anciano lo que se tomó del campamento del culto.",
			text = [=[Los garabatos arrancados del Tomo Crepuscular contenían una magia caótica, y debajo de ella había escritura élfica. El culto usaba antigua hechicería élfica para devolver al mundo a sus viejos amos. Onu se puso a averiguar cómo, antes de que sus enemigos pudieran terminar lo que habían empezado.]=],
		},
		{
			title = "La escalera bajo Mathystra",
			hint = "Lleve al Anciano lo que quedó del guardián de Mathystra.",
			text = [=[Cuando pusieron ante él el globo de agua turbia, Onu mostró algo parecido a la sorpresa. Había una escalera bajo {link:ruins-of-mathystra}Mathystra{/link}, y un guardián la había vigilado. Solo dijo que debía hablar con los demás Ancianos, y que era bueno que la escalera se hubiera encontrado antes de que la encontraran los {link:naga}naga{/link} o el culto.]=],
		},
	},
	mentions = {
		{
			text = [=[Onu, convocado por {link:barithras-moonshade}Barithras Moonshade{/link}]=],
		},
		{ text = "El campamento Crepúsculo" },
		{
			text = [=[{link:grove-of-the-ancients}Páramo de los Ancestros{/link}, un mensaje de {link:fandral-staghelm}Fandral Staghelm{/link}]=],
		},
	},
	bonds = {
		{ id = "arbal", name = "Arbal", note = "está a su lado en el páramo" },
		{ id = "barithras-moonshade", name = "Barithras Moonshade", note = "atiende sus advertencias" },
		{ id = "fandral-staghelm", name = "Fandral Staghelm", note = "le envía noticias" },
		{ id = "baron-marinous", name = "Barón Marinous", note = "el guardián de Mathystra" },
	},
})

