		{
			title = "Resumen",
			text = [=[Jai'vhanel, llamada Plumaespada, es una gran lechuza de plumas negras como el azabache. Durante mucho tiempo fue una guardiana de la tierra que rodea {link:ameth-aran}Ameth'Aran{/link}. Después enloqueció, y empezó a atacar a los viajeros en el camino a {link:auberdine}Auberdine{/link}. Nadie sabe qué la llevó a ello. Las {link:sentinels}Centinelas{/link} pusieron precio a su cabeza.]=],
		},
		{ title = "Sin registro", text = "Se desconoce la causa de su locura." },
		{
			title = "Importancia",
			text = [=[Las {link:sentinels}Centinelas{/link} no la cazaron de buen grado. Su caída es una señal más de que algo ha ido mal con las criaturas de {link:darkshore}Costa Oscura{/link}, desde los osos del bosque hasta las aves de las colinas.]=],
		},
	},
	mentions = {
		{ text = "SE BUSCA: Jai'vhanel" },
	},
	bonds = {
		{ id = "sentinel-glynda-nal-shea", name = "Centinela Glynda Nal'Shea", note = "puso la recompensa" },
	},
})

Translate("esES", "lord-sinslayer", {
	title = "Lord Sinslayer",
	subtitle = "Naga del Salto de Fonrroca",
	found = "La cueva detrás del Salto de Fonrroca",
	hint = [=[Enfréntese al señor naga que acecha en la cueva detrás del Salto de Fonrroca.]=],
	allegiance = "Naga",
	aliases = { "Sinslayer" },
	sections = {
		{
			title = "Resumen",
			text = [=[Lord Sinslayer dirige a los {link:naga}naga{/link} que han tomado la cueva detrás del {link:cliffspring-falls}Salto de Fonrroca{/link}. Los Ancianos sintieron el mal de esa cueva antes de que ningún elfo lo hubiera visto. El salto da a {link:darkshore}Costa Oscura{/link} gran parte de su agua potable, y el veneno que ahora mana de él ha enfermado a los ciervos por toda la tierra.]=],
		},
		{
			title = "Sin registro",
			text = [=[Poco se sabe de Sinslayer más allá de su nombre y su guarida.]=],
		},
		{
			title = "Importancia",
			text = [=[La cueva de Sinslayer está más cerca de {link:auberdine}Auberdine{/link} que {link:ruins-of-mathystra}Mathystra{/link}. Su presencia muestra que los {link:naga}naga{/link} ya no se conforman con las viejas ruinas del noreste.]=],
		},
	},
	bonds = {
		{ id = "barithras-moonshade", name = "Barithras Moonshade", note = "advirtió de su cueva" },
	},
})

Translate("esES", "murkdeep", {
	title = "Murkdeep",
	subtitle = "Terror de los Greymist",
	found = "Un campamento múrloc en la costa al sur de Auberdine",
	hint = "Enfréntese al múrloc que guarda las chozas de la costa sur.",
	allegiance = "Múrlocs Greymist",
	sections = {
		{
			title = "Resumen",
			text = [=[Murkdeep es un {link:murlocs}múrloc{/link} de la tribu Greymist que guarda un campamento de chozas en la costa al sur de {link:auberdine}Auberdine{/link}. Ha matado al menos a una centinela. También se cree que hundió dos barcos de carga frente a la costa. El consejo del pueblo ha puesto precio a su cabeza, y la gente del pueblo dice que dormirá más tranquila cuando se pague.]=],
		},
		{
			title = "Importancia",
			text = [=[Murkdeep es la razón de que los pescadores de {link:auberdine}Auberdine{/link} mantengan sus barcas en tierra, y de que la carga del mar llegue tarde o no llegue.]=],
		},
	},
	mentions = {
		{ text = "SE BUSCA: ¡Murkdeep!" },
	},
	bonds = {
		{ id = "sentinel-glynda-nal-shea", name = "Centinela Glynda Nal'Shea", note = "paga la recompensa" },
	},
})

Translate("esES", "kerlonian-evershade", {
	title = "Kerlonian Evershade",
	subtitle = "Druida de la Garra",
	found = "Cerca del Páramo de los Ancestros",
	hint = [=[Encuentre al druida adormilado que ha perdido sus cosas cerca del páramo del sur.]=],
	allegiance = "Druidas de la Garra",
	aliases = { "Kerlonian" },
	sections = {
		{
			title = "Resumen",
			text = [=[Kerlonian Evershade es un Druida de la Garra que ha despertado hace poco del {link:emerald-dream}Sueño Esmeralda{/link}. Desde entonces tiene sueño. Partió hacia la {link:maestra-s-post}Atalaya de Maestra{/link} para reunirse con {link:liladris-moonriver}Liladris Moonriver{/link}, se detuvo a echar una breve siesta y perdió sus pertenencias. Un cuerno en su cofre lo despertará si vuelve a quedarse dormido.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Despertó del {link:emerald-dream}Sueño Esmeralda{/link} y tomó el camino del sur hacia {link:ashenvale}Vallefresno{/link}.
• Volvió a dormirse por el camino, y necesita un guía para llegar a la {link:maestra-s-post}Atalaya de Maestra{/link}.]=],
		},
	},
	mentions = {
		{ text = "El durmiente ha despertado" },
	},
	bonds = {
		{ id = "cerellean-whiteclaw", name = "Cerellean Whiteclaw", note = "otro durmiente despertado" },
	},
})

Translate("esES", "cult-of-the-dark-strand", {
	title = "Culto de la Hebra Oscura",
	aliases = { "Hebra Oscura" },
	sections = {
		{
			title = "Resumen",
			text = [=[El Culto de la Hebra Oscura es una compañía de brujos que ha tomado la {link:tower-of-althalaxx}Torre de Althalaxx{/link} en {link:darkshore}Costa Oscura{/link}. No tenía ningún nombre conocido por las {link:sentinels}Centinelas{/link} hasta que {link:balthule-shadowstrike}Balthule Shadowstrike{/link} reconstruyó uno a partir de restos de su pergamino. Sus fanáticos e invocadores del vacío sirven a {link:athrikus-narassin}Athrikus Narassin{/link}, el antiguo señor Altonato de la torre.]=],
		},
		{
			title = "Su poder",
			text = [=[El culto se nutre de gemas de alma. {link:athrikus-narassin}Athrikus{/link} mantenía atrapadas en ellas almas de Altonato, y las escondió en las tierras de los sátiros del norte de {link:ashenvale}Vallefresno{/link}, en la {link:night-run}Senda de la Noche{/link} y en {link:satyrnaar}Satyrnaar{/link}. El culto trabaja también en {link:the-ruins-of-ordil-aran}Las Ruinas de Ordil'Aran{/link}, en Vallefresno. Tiene tratos con el brujo {link:orcs}orco{/link} {link:ilkrud-magthrull}Ilkrud Magthrull{/link}, del {link:fire-scar-shrine}Santuario de la Escara{/link}, que tomaba notas de sus planes. {link:delgren-the-purifier}Delgren el Purificador{/link} ha hecho de acabar con él su tarea.]=],
		},
	},
})

Translate("esES", "blackwood-furbolgs", {
	title = "Fúrbolgs Bosque Negro",
	aliases = { "Bosque Negro", "tribu Bosque Negro" },
	sections = {
		{
			title = "Resumen",
			text = [=[Los Bosque Negro son una tribu de {link:furbolgs}fúrbolgs{/link} de {link:darkshore}Costa Oscura{/link}. Fueron amigos de los elfos de la noche, y los elfos aún los recuerdan así. Ahora están corrompidos. Viven en campamentos a lo largo del {link:cliffspring-river}Río Fonrroca{/link}, en el norte, y en el sur, y atacan a todo elfo que se acerca.]=],
		},
		{
			title = "La corrupción",
			text = [=[Los elfos de {link:auberdine}Auberdine{/link} han atribuido parte de la locura de los Bosque Negro a los sátiros. Un corruptor {link:satyrs}sátiro{/link} los domina mediante un talismán. Cuando los fúrbolgs comieron alimentos mezclados con agua de la poza de la Luna, quedaron purificados por poco tiempo. El anciano de Auberdine espera que algún día puedan ser liberados para siempre. Sin embargo, el veneno más profundo corre por la tierra y el agua, y viene de {link:felwood}Frondavil{/link}.]=],
		},
	},
})
